"""Isolated dataset factory registration; no training or held-out generation access."""
import hashlib,json,sys,urllib.request
from pathlib import Path
from datetime import datetime,timezone,timedelta
ROOT=Path(__file__).resolve().parents[2]
def sha(path):return hashlib.sha256(path.read_bytes()).hexdigest()
def save(path,value):path.write_text(json.dumps(value,indent=2,ensure_ascii=False),encoding='utf-8')
def get(url):
    with urllib.request.urlopen(url,timeout=90) as r:return r.read()
def main():
    out=ROOT/'evidence/qlora-dataset-factory'/datetime.now(timezone(timedelta(hours=5,minutes=30))).strftime('%Y%m%d-%H%M%S');out.mkdir(parents=True)
    (out/'PREREGISTRATION.md').write_text('''# Universal QLoRA dataset factory preregistration
Preparation only, no full training/deployment, no production modification or concurrent heavy model. Target official Qwen/Qwen3.5-4B-Base, exact revision pinned from API. Existing Qwen3.5-4B GGUF is instruction-tuned self-generation teacher, NOT Base baseline. Teacher provenance/license explicitly recorded. Download tokenizer/config/license only; no Base weights/heavy training on laptop. Training stack isolated and pinned for later approved NVIDIA environment.
Holdout T01–T15 and any known held-out trajectories excluded from candidate prompts/demonstrations/generation/templates. Generation code cannot import benchmark tasks/results. After independently authored candidates freeze, a separate scanner may read holdout signatures for rejection only. Scanner output contains scores/rejections, never solutions in dataset. No example derived from old benchmark or coverage fixture rp07. Existing RAG experiment raw answers may be screened only if from authentic README and not heldout; prior failures remain separate negatives, never corrected.
Start with a verified seed, not a padded1000row release. Seven categories; desired30/25/20/10/5/5/5mix. Pilot scale100–300per major remains a later acquisition goal, never claim met by repeated parameter sweeps. Each authored seed task uses distinct families; variants stay family-isolated across80/10/10splits. Exact/normalized/near-duplicate and action-sequence reports. Category imbalance and sparse split limitations block readiness; do not fabricate data to rebalance.
Model-produced agentic/coding candidates use actual native ToolRegistry/permissions/validation and existing single Qwen worker, original request immutable, model max4096/temp0/thinkingfalse/context16384/KVq8_0q8_0. Independent oracles authored before model output in disposable fixture. One attempt/task, no external paid teacher, no invisible argument/code correction. Raw calls/events/Docker results preserved. Failed candidates separate negative/quarantine; missing independent oracle excludes sample. Prefer successful zero-repair seeds; repair-training segments require independent attribution, never train wrong initial action as correct. Final task success requires READY_FOR_REVIEW plus independent oracle and preserved unrelated files; no publication.
RAG controlled synthetic sources labeled synthetic, project text byte-exact source digest, no fabricated project facts. Reference targets labeled programmatic_reference, not model outputs; exact grounding/algebra checks required. No paid/public training dataset without license review; public model docs are metadata, not default SFT corpus. General QA stable factual closed-scope definitions quality-reviewed with source provenance; uncertain facts quarantined. Computation verified against Decimal/Fraction independent symbolic expectations, deterministic tool outputs not model intelligence claims. Safety follows real permission checks; do not teach excessive refusal.
Canonical messages preserve production tool_calls list/function/name/arguments, role tool/tool_call_id; never singular invented tool_call. Official pinned tokenizer/template tested on representative conversations and tools. Train on each eligible assistant completion only using prompt-completion data, not on fabricated tool outputs; official template lacks generation blocks so no assumed assistant_only_loss masks. Prefix compatibility must be tested. No silent truncation; oversize examples quarantined. Report actual token percentiles and planned2048or4096based on observed data/VRAM gate. CPU format tests do not prove CUDA QLoRA execution.
QLoRA conservative NF4/doublequant rank16/alpha32/dropout.05/all-linear excluding visual modules/lr1e-4/epochs2/micro1/accum16/checkpointing/bf16if supported fp16otherwise. Pinned versions/source APIs checked; executable preflight must reject missingCUDA, bad serialization, contaminated datasets, unverified/imbalanced release, and unchanged Base-baseline gate. Baseline true Base model not available on laptop: report NOT_RUN, never substitute instruct GGUF. Colab script enables separate approved evaluation before training. Checkpoints validation-only, no holdout for tuning. Forgetting test plan seven domains plus followups; final holdout only after freeze.
Stop with DATASET_NEEDS_MORE_DATA/QUALITY_BLOCKED/FORMAT_BLOCKED as appropriate if pilot volume/coverage/GPU verification or baseline incomplete. Preserve valid audited seeds even when not training-ready. No T10/Stage1B/Stage2 experiment resumed. All artifacts/hashes/report required, unknowns explicit.
''',encoding='utf-8')
    api=json.loads(get('https://huggingface.co/api/models/Qwen/Qwen3.5-4B-Base'));revision=api['sha'];assets=out/'base-tokenizer';assets.mkdir()
    metadata={}
    for name in ('config.json','tokenizer_config.json','tokenizer.json','merges.txt','vocab.json','LICENSE','README.md'):
        p=assets/name;p.write_bytes(get(f'https://huggingface.co/Qwen/Qwen3.5-4B-Base/resolve/{revision}/{name}'));metadata[name]=sha(p)
    versions={p:json.loads(get('https://pypi.org/pypi/'+p+'/json'))['info']['version'] for p in ('transformers','trl','peft','bitsandbytes','accelerate','datasets','torch')}
    save(out/'upstream.json',{'base_model':'Qwen/Qwen3.5-4B-Base','revision':revision,'license':'apache-2.0','assets_sha256':metadata,'pypi_versions':versions,'sources':['https://huggingface.co/Qwen/Qwen3.5-4B-Base','https://huggingface.co/docs/trl/en/sft_trainer','https://huggingface.co/docs/peft/en/developer_guides/quantization']})
    protected={str(p.relative_to(ROOT)):sha(p) for folder in ('backend','router','rag','workflows','scripts','evidence/json-action-adapter-v2') for p in (ROOT/folder).rglob('*') if p.is_file() and '__pycache__' not in str(p)}
    protected['models/Qwen3.5-4B-Q4_K_M.gguf']=sha(ROOT/'models/Qwen3.5-4B-Q4_K_M.gguf')
    save(out/'manifest.json',{'preregistration_sha256':sha(out/'PREREGISTRATION.md'),'production_and_frozen_sha256':protected,'base_model':'Qwen/Qwen3.5-4B-Base','base_revision':revision,'training_started':False,'base_weights_downloaded':False,'production_modified':False})
    components=[('model','backend/model.py','Local HTTP structured generation/tool turns','messages/tools/schema','raw/provider response','complete; agent_tool_turn','GGUF deployed teacher is not Base','exact action serialization and refusal/grounded answer formats'),('router','backend/service.py','Existing request dispatch with literal arithmetic/document/conversation branches','request/context/history','capability/workflow','ask/agent','bare followups can bypass evidence','domain-appropriate action choice'),('broker','router/model_broker.py','Model selection/admission and registry lease','role/resources','selection/acquisition','select/acquire','one heavy model; no universal quality proof','selection is not authority'),('native_registry','workflows/agent_kernel.py','Tool schemas and permissions','name/arguments','validated native observation','list_dir/read_file/search_code/write_file/apply_patch/delete_file/run_command/run_tests/inspect_process/finish','file tools operate on virtual draft; finish independently validates','tool contracts and stateful verification'),('sandbox','router/sandbox.py','Fail-closed pinned Docker execution','script/input snapshot','exit/stdout/stderr','execute','offline/nonroot/read-only root; source shell edits discarded','no host/network bypass'),('rag','rag/retrieve.py','Persisted vectors plus FTS5 BM25/RRF','question/scope','deduped chunks','retrieve','active vectors reload; top-k can omit relation','grounding rather than word coincidence'),('history','rag/answer.py','Evidence prompts and bounded validation/repair','question/sources/prior user questions','status/answer/citations','answer','prior answers/evidence not carried by bare question history','explicit referent and evidence scope'),('embedding','rag/embedding.py','Pinned BGE-small ONNX CPU embeddings','texts/query flag','normalized384vectors','encode','512token input bound; initialization cold cost','not replaced by training'),('ingestion','rag/ingest.py','Offline extract/chunk structured documents','sourcebytes','pages/chunks','extract/chunk_pages','format/source coverage limitations','source provenance'),('calculator','rag/calculator.py','Allowlisted Decimal AST arithmetic','formal expression','verified result','literal_expression/calculate','percent word supported; percent symbol bypass observed','prefer deterministic computation'),('publication','workflows/coding_workspace.py','Drafts/revision checks/explicit accept','workspace/task/diff','reviewed changes','stage/accept/discard','no automatic publication','finish != publish')]
    save(out/'repository-capability-inventory.json',[{'component':c,'location':l,'purpose':p,'inputs':i,'outputs':o,'available_actions':a,'limitations':lim,'training_relevance':t,'source_sha256':sha(ROOT/l)} for c,l,p,i,o,a,lim,t in components])
    print(out,flush=True)
if __name__=='__main__': main()
